python3 - <<'EOF'
import json,collections
W="../paperless-ngx-bare-opus-yrwscM__work/otel-capture/traces.jsonl"
code=collections.Counter(); urls=collections.Counter(); stor=[]
for line in open(W):
    d=json.loads(line)
    for rs in d.get('resourceSpans',[]):
        for ss in rs.get('scopeSpans',[]):
            for s in ss.get('spans',[]):
                A={a['key']:list(a['value'].values())[0] for a in s.get('attributes',[])}
                if 'code.file.path' in A: code[(A['code.file.path'],A.get('code.function.name'))]+=1
                if 'http.url' in A: urls[(s['name'],A['http.url'],A.get('http.status_code'),A.get('user_agent.original') or A.get('http.user_agent'))]+=1
                if 'storage' in s['name'] or 'status' in s['name']: stor.append((s['name'],A.get('http.status_code'),s.get('status'),[e.get('name') for e in s.get('events',[])]))
for k,v in code.most_common(60): print(v,k)
print()
for k,v in urls.most_common(40): print(v,k)
print(stor)
EOF

python3 - <<'EOF'
import json
d=json.load(open('/tmp/osv-prod.json'))
want={'jinja2','django','djangorestframework','django-allauth','bleach','sqlparse','pyjwt','python-dotenv','requests','urllib3','filelock','pdfminer-six','lxml','tornado'}
for r in d['results']:
  for p in r['packages']:
    n=p['package']['name']
    if n not in want: continue
    print('==',n,p['package']['version'])
    for v in p['vulnerabilities']:
      if not v['id'].startswith('GHSA'): continue
      fixed=set()
      for a in v.get('affected',[]):
        for rg in a.get('ranges',[]):
          for e in rg.get('events',[]):
            if 'fixed' in e: fixed.add(e['fixed'])
      print('  ',v['id'],sorted(fixed),v.get('summary','')[:100])
EOF
